// Pre-compute recipes grouped data
export function getRecipes(data) {
  const recipeMap = {};
  data.forEach(item => {
    const key = item.RecipeSuggestion;
    if (!recipeMap[key]) {
      recipeMap[key] = {
        name: key,
        ingredients: [],
        totalPrice: 0,
        totalOriginalPrice: 0,
        totalProtein: 0,
        totalCarbs: 0,
        totalFat: 0,
        totalFiber: 0,
        image: recipeImages[key] || item.Image_Url, // Map to local dish image asset
      };
    }
    recipeMap[key].ingredients.push(item);
    recipeMap[key].totalPrice += item.DiscountPrice;
    recipeMap[key].totalOriginalPrice += item.Price;
    recipeMap[key].totalProtein += item.Protein;
    recipeMap[key].totalCarbs += item.Carbs;
    recipeMap[key].totalFat += item.Fat;
    recipeMap[key].totalFiber += item.Fiber;
  });

  return Object.values(recipeMap).map(r => ({
    ...r,
    totalPrice: Math.round(r.totalPrice * 100) / 100,
    totalOriginalPrice: Math.round(r.totalOriginalPrice * 100) / 100,
    totalProtein: Math.round(r.totalProtein),
    avgProteinPerIngredient: Math.round(r.totalProtein / r.ingredients.length),
    discount: Math.round(((r.totalOriginalPrice - r.totalPrice) / r.totalOriginalPrice) * 100),
  }));
}

